    const ring = [[51.4,-61.1],[52.6,-103.1],[55.5,-106.1],[131.1,-104.8],[138.4,-105.7],[165.2,-107.2],[168.5,-99.7],[161.8,-92.7],[163.7,-90.6],[163.9,-66.0],[158.5,-66.1],[158.2,-49.3],[58.3,-48.9],[58.2,-61.2]];
