    nwShaft(g, T, [[51.6,-106],[150,-106],[150,-64],[51.6,-64]], [[51.6,-106],[119,-106],[119,-64],[51.6,-64]], 133, [395, 395, 368, 368], G30, FIN, 3.0);
    nwShaft(g, T, [[58.5,-64],[150,-64],[150,-49.5],[58.5,-49.5]], [[58.5,-64],[125,-64],[125,-49.5],[58.5,-49.5]], 133, [312, 312, 300, 300], G30, FIN, 3.0);
    for (let i = 0; i < 4; i++){ const x = [51.6, 150, 150, 51.6][i]; }
    // fins on the podium
